import{selectedGameplayMap}from'./selected-geometry.mjs';
// Preserve original scene/clock/port/session identity. Separate gameplay reader avoids widening warp DTO.
export function attachSelectedGameplay(scene,{geometry,getWorld}){if(typeof getWorld!=='function'||typeof scene?.readNative!=='function')throw Error('CURRENT_TARGET_SCENE_REQUIRED');const map=selectedGameplayMap(geometry,scene.mapId),originalInspect=scene.inspect.bind(scene),originalRead=scene.readNative.bind(scene),originalHint=scene.proximityHint.bind(scene),safe=map.safeMask(),n=originalRead();if(!n||safe[n.foot[1]*1536+n.foot[0]]!==1)throw Error('RESTORED_FOOT_INTERSECTS_SELECTED_NPC_HOLD');const lifecycle=new AbortController(),dispose=scene.dispose.bind(scene);scene.getGameplaySignal=()=>lifecycle.signal;scene.dispose=()=>{lifecycle.abort();dispose()};scene.mask=safe;scene.readGameplayNative=()=>{const r=originalRead();return r?{...r,gameplayRevision:'S4_SELECTED_FIVE_INTERACTIONS_R1'}:null};scene.proximityHint=()=>{const r=originalRead(),p=r&&map.pointAt(r.foot,r.facing);return p?p.kind==='trainer'?'트레이너와 이야기하기 · 조사':p.kind==='event'?'역사 안내판 읽기 · 조사':'관찰 장소 조사하기 · 조사':originalHint()};scene.inspect=async execution=>{const w=getWorld();if(!w||scene.world!==w||scene.disposed||scene.locked||w.busy||w.inputLocked)throw Error('INPUT_LOCKED');const r=originalRead(),p=r&&map.pointAt(r.foot,r.facing);if(!p)return originalInspect(execution);let result;try{result=await w.interactNativeS4Gameplay(p.pointId,{type:p.kind})}catch(error){const explanations={AREA_STAGE_LOCKED:'아직 이 지역의 진행 조건을 충족하지 못했습니다.',ACQUISITION_STAGE_LOCKED:'아직 이 관찰의 진행 조건을 충족하지 못했습니다.',EVENT_GATE_LOCKED:'이 관찰에 필요한 원래 선행 조건이나 도감 등록이 부족합니다.',EVENT_ORDER_LOCKED:'먼저 원래 선행 사건을 완료해 주세요.',FIELD_REQUIREMENT_LOCKED:'이 관찰에 필요한 원래 현장 조건을 충족하지 못했습니다.','Storage full; acquisition not committed':'동료와 보관함이 가득 차 관찰 결과를 받을 수 없습니다. 공간을 비운 뒤 다시 조사해 주세요.','Base registration proof required for this existing chain':'이미 보유한 진화 계열의 기본 도감 등록을 먼저 확인해 주세요.'};const message=p.kind==='acquisition'&&typeof error?.message==='string'&&Object.hasOwn(explanations,error?.message)?explanations[error.message]:null;if(typeof message==='string'){const shown=new Error(message,{cause:error});shown.code=error.message;throw shown}throw error}const gameplayNotice=p.kind==='acquisition'?(result?.alreadyCompleted===true?'이미 관찰을 완료한 장소입니다. 도감과 보관함을 확인해 주세요.':result?.completed===true?'관찰을 완료했습니다. 도감과 동료·보관함에 반영된 결과를 확인해 주세요.':'관찰이 완료되지 않았습니다.'):p.kind==='event'?(result?.alreadyCompleted===true?'이미 확인한 역사 안내입니다.':result?.completed===true?'역사 안내 확인을 완료했습니다.':undefined):undefined;return{...result,gameplayHandled:true,...(gameplayNotice?{gameplayNotice}:{})}};return scene}
